<main id="fixture-main">
  <h1>Svelte fixture</h1>
  <uv-alert title="Custom Elements">No Vue host application required.</uv-alert>
  <uv-slider label="Coverage" model-value="74" value-suffix="%" show-value></uv-slider>
  <uv-combobox label="Framework" model-value="svelte" options-json={optionsJson}></uv-combobox>
  <uv-date-picker label="Release date" model-value="2026-07-01" locale="en-US"></uv-date-picker>
  <uv-number-input label="Replicas" model-value="3" min="1" max="10"></uv-number-input>
  <uv-rating label="Documentation quality" model-value="4" show-value></uv-rating>
  <uv-tag-input label="Tags" values-json={tagsJson} suggestions-json={suggestionsJson}></uv-tag-input>
  <uv-form-field label="Repository URL" hint="A native Svelte input stays in light DOM." for-id="svelte-repository"><input id="svelte-repository" value="https://github.com/universal-vue/components" /></uv-form-field>
  <uv-fieldset legend="Outputs" layout="inline"><label><input type="checkbox" checked /> Elements</label><label><input type="checkbox" checked /> CDN</label></uv-fieldset>
  <uv-stepper model-value="integrate" steps-json={stepsJson}></uv-stepper>
  <uv-command-palette mode="inline" commands-json={commandsJson}></uv-command-palette>
  <uv-timeline label="Svelte integration" items-json={timelineJson}></uv-timeline>
  <uv-calendar model-value="2026-06-20" locale="en-US"></uv-calendar>
  <uv-file-upload label="Package artifact" accept=".zip,.tgz"></uv-file-upload>
  <uv-table caption="Batch 04 components" columns-json={columnsJson} rows-json={rowsJson} selectable></uv-table>
  <uv-toast position="inline" items-json={toastJson}></uv-toast>
  <uv-divider label="Loading preview"></uv-divider>
  <uv-skeleton lines="2"></uv-skeleton>
  <uv-button variant="primary">Continue</uv-button>
  <uv-button variant="outline" onclick={openDrawer}>Open drawer</uv-button>
  <uv-drawer bind:this={drawer} title="Svelte drawer" description="Controlled through a DOM property.">Svelte can project normal light-DOM content.</uv-drawer>

  <uv-empty-state title="No saved presets" description="Create a preset to continue." tone="info"><uv-button size="sm">Create preset</uv-button></uv-empty-state>
  <uv-toolbar label="Editor actions"><uv-button size="sm" variant="ghost">Bold</uv-button><uv-button size="sm" variant="ghost">Italic</uv-button></uv-toolbar>
  <uv-sidebar label="Svelte navigation"><a href="#components">Components</a><br /><a href="#guides">Guides</a></uv-sidebar>
  <uv-tree-view label="Component tree" nodes-json={treeJson} expanded-json={expandedJson}></uv-tree-view>
  <uv-carousel label="Distribution formats" items-json={carouselJson}></uv-carousel>
  <!-- Batch 06 -->
  <uv-search-input label="Search components" model-value="button"></uv-search-input>
  <uv-password-input label="Package token" show-strength></uv-password-input>
  <uv-otp-input label="Verification code" length="4"></uv-otp-input>
  <uv-color-picker label="Brand color" swatches-json={batch6SwatchesJson}></uv-color-picker>
  <uv-range-slider label="Coverage range" values-json={batch6RangeJson}></uv-range-slider>

  <!-- Batch 07 -->
  <uv-toggle label="Pin component" model-value="true"></uv-toggle>
  <uv-toggle-group label="Formatting" multiple options-json={batch7ToggleOptionsJson}></uv-toggle-group>
  <uv-segmented-control label="Layout" model-value="grid" options-json={batch7SegmentOptionsJson}></uv-segmented-control>
  <uv-button-group label="History" attached><uv-button variant="outline">Undo</uv-button><uv-button variant="outline">Redo</uv-button></uv-button-group>
  <uv-split-button label="Save" items-json={batch7SplitItemsJson}></uv-split-button>

  <!-- Batch 08 -->
  <uv-link href="https://github.com" target="_blank" external>Repository</uv-link>
  <uv-skip-link href="#fixture-main">Skip to fixture</uv-skip-link>
  <uv-navigation-menu label="Fixture navigation" items-json={batch8NavigationJson}></uv-navigation-menu>
  <uv-menubar label="Fixture menu" items-json={batch8MenubarJson}></uv-menubar>
  <uv-bottom-navigation model-value="home" label="Destinations" items-json={batch8BottomJson}></uv-bottom-navigation>

  <!-- Batch 09 -->
  <uv-alert-dialog title="Delete item?" description="This cannot be undone." danger><uv-button slot="trigger" variant="danger">Delete</uv-button></uv-alert-dialog>
  <uv-hover-card><span slot="trigger">Package details</span><p>Universal components work in every supported host.</p></uv-hover-card>
  <uv-collapsible title="Package details"><p>Native Vue and Custom Element outputs are included.</p></uv-collapsible>
  <uv-scroll-area label="Release log" max-height="7rem"><p>Batch 09 adds accessible overlays and layout helpers.</p><p>Keyboard and focus behavior remain portable.</p></uv-scroll-area>
  <uv-aspect-ratio ratio="16/9" label="Preview"><div>Responsive preview</div></uv-aspect-ratio>

  <!-- Batch 10 -->
  <uv-description-list label="Package details" bordered items-json={batch10DescriptionsJson}></uv-description-list>
  <uv-stat label="Components" value="70" trend="5" trend-direction="up" trend-label="this batch"></uv-stat>
  <uv-code-block code="import { UvButton } from '@universal-vue/vue'" language="ts" line-numbers></uv-code-block>
  <uv-listbox multiple searchable label="Frameworks" options-json={batch10ListboxJson}></uv-listbox>
  <uv-transfer-list items-json={batch10TransferItemsJson} values-json={batch10TransferValuesJson} source-label="Available" target-label="Enabled"></uv-transfer-list>

  <section aria-label="Batches 11 through 1000 Custom Elements">
    {#each generatedComponents as demo}
      <svelte:element this={demo.tag} label={demo.label} title={demo.label} description="Svelte Custom Element fixture." value="Ready" items-json={generatedItemsJson} values-json={generatedValuesJson}></svelte:element>
    {/each}
  </section>

</main>

